import type {SessionCursor, SessionSummary} from './sessionStore.js';

describe('WebSocket message types for session listing', () => {
  it('types compile and can be used to validate list_sessions frame structure', () => {
    // RED: types ListSessionsMessage and SessionListMessage do not exist yet
    // This test validates that the types are properly exported and have the correct shape

    const incomingFrame: ListSessionsMessage = {
      type: 'list_sessions',
